function updateSEO(r,t,visible){
  const post=articles.find(a=>a.slug===r.sub);
  const special=r.page==='investment'?citizenshipContent.guide[r.lang]:r.page==='igaturkishcitizenshipbyinvestment'?citizenshipContent.lawyer[r.lang]:null;
  const service=services.find(item=>item.path===r.page);
  const homeTitle={en:'International Legal Counsel in Istanbul',tr:'İstanbul’da Uluslararası Hukuki Danışmanlık',zh:'伊斯坦布尔国际法律咨询',ar:'استشارات قانونية دولية في إسطنبول'};
  const pageTitle={services:pageSeo[r.lang].services.title,team:pageSeo[r.lang].team.title,about:pageSeo[r.lang].about.title,contact:pageSeo[r.lang].contact.title,journal:pageSeo[r.lang].journal.title};
  const finalMeta=window.finalSeoMetadata?.[pathFor(r.lang,r.page,r.sub)];
  const title=migratedService(r.lang,r.page)?.title||finalMeta?.title||special?.title||(post?(r.lang==='en'&&window.seoOptimizations?.articles?.[post.slug]?.title||`${articleSearchTitle(post,r.lang)} | IGA Law Firm`):service?`${serviceData[service.id].title[r.lang]} | IGA Law Firm`:pageTitle[r.page]||pageSeo[r.lang]?.[r.page]?.title||'IGA Law Firm');
  const description=migratedService(r.lang,r.page)?.description||finalMeta?.description||special?.description||(post?articleDescription(post,r.lang):service?serviceData[service.id].desc[r.lang]:pageSeo[r.lang]?.[r.page]?.description||t.practiceIntro);
  const normalizedLang=r.lang==='zh'?'zh-CN':r.lang;
  const url='https://igalawfirm.com'+pathFor(r.lang,r.page,r.sub);
  document.title=title;
  document.documentElement.lang=normalizedLang;
  document.documentElement.dir=r.lang==='ar'?'rtl':'ltr';
  let canonical=document.querySelector('link[rel="canonical"]');
  if(!canonical){canonical=document.createElement('link');canonical.rel='canonical';document.head.appendChild(canonical)}
  canonical.href=url;
  function setMeta(selector,attribute,value){let item=document.querySelector(selector);if(!item){item=document.createElement('meta');const separator=attribute.indexOf(':');item.setAttribute(attribute.slice(0,separator),attribute.slice(separator+1));document.head.appendChild(item)}item.content=value}
  setMeta('meta[name="description"]','name:description',description);
  setMeta('meta[property="og:title"]','property:og:title',title);
  setMeta('meta[property="og:description"]','property:og:description',description);
  setMeta('meta[property="og:url"]','property:og:url',url);
  setMeta('meta[property="og:locale"]','property:og:locale',r.lang==='zh'?'zh_CN':r.lang==='ar'?'ar_AR':r.lang==='tr'?'tr_TR':'en_US');
  setMeta('meta[name="twitter:title"]','name:twitter:title',title);
  setMeta('meta[name="twitter:description"]','name:twitter:description',description);
  const old=document.getElementById('iga-structured-data');if(old)old.remove();
  const org={'@type':['Organization','LegalService'],'@id':'https://igalawfirm.com/#organization','name':'IGA Law Firm','url':'https://igalawfirm.com','email':'info@igalawfirm.com','telephone':'+90 530 426 46 12','logo':'https://igalawfirm.com/public/assets/iga-logo.png'};
  org.address={'@type':'PostalAddress','streetAddress':'Bebek Mahallesi, Cevdetpaşa Caddesi, Eczane Çıkmazı Sokak No:4/1','addressLocality':'Beşiktaş','addressRegion':'Istanbul','addressCountry':'TR'};
  const site={'@type':'WebSite','@id':'https://igalawfirm.com/#website','name':'IGA Law Firm','url':'https://igalawfirm.com','publisher':{'@id':org['@id']}};
  const page={'@type':r.page==='journal'&&!post?'CollectionPage':'WebPage','@id':url+'#webpage','url':url,'name':title,'description':description,'inLanguage':normalizedLang,'isPartOf':{'@id':site['@id']}};
  if(r.page==='home'){
    page.mainEntity={'@id':org['@id']};
    org.areaServed={'@type':'Country','name':'Türkiye'};
    org.knowsAbout=['Turkish citizenship by investment','Turkish real estate transactions','Immigration and residence in Türkiye','Turkish corporate and commercial law','Litigation and dispute resolution in Türkiye'];
  }
  const graph=[org,site,page];
  if(service||r.page==='igaturkishcitizenshipbyinvestment'){
    const lawyerPage=r.page==='igaturkishcitizenshipbyinvestment';
    const propertyPage=service?.id==='property'&&r.lang==='en'&&window.realEstatePillar;
    const serviceName=migratedService(r.lang,r.page)?.h1|| (propertyPage?window.realEstatePillar.h1:lawyerPage?citizenshipContent.lawyer[r.lang].h1:serviceData[service.id].title[r.lang]);
    const serviceDescription=propertyPage?window.realEstatePillar.description:lawyerPage?citizenshipContent.lawyer[r.lang].description:serviceData[service.id].desc[r.lang];
    graph.push({'@type':'Service','@id':url+'#service','name':serviceName,'description':serviceDescription,'url':url,'provider':{'@id':org['@id']}});
    const faqs=propertyPage?window.realEstatePillar.faq:lawyerPage?(window.citizenshipCommercial?.[r.lang]?.faq||citizenshipContent.lawyer[r.lang].faq):serviceFaqEntries(migratedService(r.lang,r.page)?serviceData[service.id].title[r.lang]:serviceName,serviceDescription,t,r.lang);
    graph.push({'@type':'FAQPage','@id':url+'#faq','mainEntity':faqs.map(([question,answer])=>({'@type':'Question','name':question,'acceptedAnswer':{'@type':'Answer','text':answer}}))});
    graph.push({'@type':'BreadcrumbList','@id':url+'#breadcrumb','itemListElement':[{'@type':'ListItem','position':1,'name':t.home,'item':'https://igalawfirm.com'+pathFor(r.lang,'home')},{'@type':'ListItem','position':2,'name':t.nav[1],'item':'https://igalawfirm.com'+pathFor(r.lang,'services')}]});
  } else if(r.page==='services') {
    graph.push({'@type':'BreadcrumbList','@id':url+'#breadcrumb','itemListElement':[{'@type':'ListItem','position':1,'name':t.home,'item':'https://igalawfirm.com'+pathFor(r.lang,'home')},{'@type':'ListItem','position':2,'name':t.nav[1],'item':url}]});
  }
  if(post){const article={'@type':'BlogPosting','@id':url+'#article','url':url,'headline':articleTitle(post,r.lang),'description':description,'inLanguage':normalizedLang,'mainEntityOfPage':{'@id':page['@id']},'publisher':{'@id':org['@id']}};if(post.publishedAt||window.articleArchiveDates?.[post.slug])article.datePublished=post.publishedAt||window.articleArchiveDates[post.slug];const edited=post.updatedAt||window.articleContentUpdates?.[post.slug]||window.seoOptimizations?.articles?.[post.slug]?.updated;if(edited)article.dateModified=edited;const image=window.blogPostContent?.[post.slug]?.heroImage;if(image)article.image=image.startsWith('http')?image:'https://igalawfirm.com/'+image.replace(/^\//,'');const imageCopy=r.lang==='en'?window.blogPostContent?.[post.slug]:window.blogPostTranslations?.[r.lang]?.[post.slug];if(image&&imageCopy?.imageDescription){article.associatedMedia={'@type':'ImageObject','contentUrl':article.image,'name':imageCopy.imageTitle,'description':imageCopy.imageDescription,'caption':imageCopy.imageAlt,'inLanguage':normalizedLang};setMeta('meta[property="og:image:alt"]','property:og:image:alt',imageCopy.imageAlt);setMeta('meta[name="twitter:image:alt"]','name:twitter:image:alt',imageCopy.imageAlt)}graph.push(article);graph.push({'@type':'BreadcrumbList','@id':url+'#breadcrumb','itemListElement':[{'@type':'ListItem','position':1,'name':t.home,'item':'https://igalawfirm.com'+pathFor(r.lang,'home')},{'@type':'ListItem','position':2,'name':t.nav[5],'item':'https://igalawfirm.com'+pathFor(r.lang,'journal')},{'@type':'ListItem','position':3,'name':articleTitle(post,r.lang),'item':url}]})}
  else if(r.page==='journal')graph.push({'@type':'BreadcrumbList','@id':url+'#breadcrumb','itemListElement':[{'@type':'ListItem','position':1,'name':t.home,'item':'https://igalawfirm.com'+pathFor(r.lang,'home')},{'@type':'ListItem','position':2,'name':t.nav[5],'item':url}]});
  window.igaSchemaContent.enhance(graph,{route:r,t,...visible,canonical:url,language:normalizedLang,team,anchors:homeTeamAnchors,services,serviceData,practiceAreaCopy,pathFor,post});
  const script=document.createElement('script');script.id='iga-structured-data';script.type='application/ld+json';script.textContent=JSON.stringify({'@context':'https://schema.org','@graph':graph});document.head.appendChild(script);
}

function serviceFaqEntries(title,description,t,lang){return lang==='tr'?[[`${title} hangi konuları kapsar?`,description],['Ekiple nasıl iletişim kurabilirim?',t.contactText]]:lang==='zh'?[[`${title}包括哪些内容？`,description],['如何联系团队？',t.contactText]]:lang==='ar'?[[`ما الموضوعات التي تشملها خدمة ${title}؟`,description],['كيف أتواصل مع الفريق؟',t.contactText]]:[[ `What does ${title} cover?`,description],['How can I contact the team?',t.contactText]]}
function faqMarkup(rows){return `<section class="service-faq"><h2>${locale==='tr'?'Sık sorulan sorular':locale==='zh'?'常见问题':locale==='ar'?'الأسئلة الشائعة':'Frequently asked questions'}</h2><div class="citizenship-faq">${rows.map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</div></section>`}
function contactFormMarkup(t){return `<form class="contact-form" id="contact-form" action="/api/contact" method="post"><div aria-hidden="true" style="position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);clip-path:inset(50%);white-space:nowrap;border:0"><label>Website<input name="_iga_website" tabindex="-1" autocomplete="off"></label></div><label>${t.name}<input name="name" required autocomplete="given-name"></label><label>${t.surname}<input name="surname" required autocomplete="family-name"></label><label>${t.email}<input type="email" name="email" required autocomplete="email"></label><label>${t.phone}<input type="tel" name="phone" autocomplete="tel"></label><label class="wide">${t.message}<textarea name="message" required></textarea></label><button class="button" type="submit">${t.send} ↗</button><p class="form-note wide" id="form-note" data-form-status role="status" aria-live="polite">${t.legalText}</p></form>`}
function contactFormSection(t,lang){return `<section class="section compact contact-form-section"><div class="shell"><div class="section-head"><div><span class="eyebrow">${t.contactEyebrow}</span><h2>${t.formTitle}</h2></div><p>${t.contactText}</p></div>${contactFormMarkup(t)}</div></section>`}
function contactPreview(t,lang){return contactFormSection(t,lang)}
function footer(t,lang){return `<footer class="footer"><div class="shell"><div class="footer-main"><div class="footer-intro"><a class="brand footer-brand" href="${pathFor(lang)}" aria-label="IGA Law Firm">${brandMarkup}</a><p>${t.footerText}</p></div><div class="footer-col"><h4>${t.quickLinks}</h4><a href="${pathFor(lang,'services')}">${t.nav[1]}</a><a href="${pathFor(lang,'investment')}">${citizenshipContent.guide[lang].h1}</a><a href="${pathFor(lang,'igaturkishcitizenshipbyinvestment')}">${citizenshipContent.lawyer[lang].h1}</a><a href="${pathFor(lang,'team')}">${t.nav[3]}</a><a href="${pathFor(lang,'journal')}">${t.nav[5]}</a></div><div class="footer-col"><h4>${t.addressLabel}</h4><p>${t.address}</p><a href="mailto:info@igalawfirm.com">info@igalawfirm.com</a><a href="tel:+905304264612">+90 530 426 46 12</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} IGA LAW FIRM</span><span>${t.legal}: ${t.legalText}</span><a href="#top" onclick="window.scrollTo({top:0,behavior:'smooth'})">${t.backTop} ↑</a></div></div></footer>`}
function wire(){const lang=document.getElementById('language');lang.querySelector('button').addEventListener('click',()=>{lang.classList.toggle('open');lang.querySelector('button').setAttribute('aria-expanded',lang.classList.contains('open'))});document.querySelector('.menu-toggle').addEventListener('click',()=>document.getElementById('mobile-menu').classList.toggle('open'));wireFloatingContact()}
function wireFloatingContact(){const trigger=document.getElementById('wechat-trigger'),modal=document.getElementById('wechat-modal');if(!trigger||!modal)return;const dialog=modal.querySelector('[role="dialog"]'),closeButton=document.getElementById('wechat-close'),copyButton=document.getElementById('wechat-copy'),status=document.getElementById('wechat-copy-status'),qr=document.getElementById('wechat-qr-image'),fallback=document.getElementById('wechat-qr-fallback');let returnFocus=null,statusTimer;const close=()=>{if(modal.hidden)return;modal.hidden=true;trigger.setAttribute('aria-expanded','false');if(returnFocus)returnFocus.focus()};const open=()=>{returnFocus=document.activeElement;modal.hidden=false;trigger.setAttribute('aria-expanded','true');closeButton.focus()};trigger.addEventListener('click',()=>{if(!/Android|iPhone|iPad|iPod/i.test(navigator.userAgent)){open();return}window.location.href=CONTACT_CONFIG.wechatChatUrl;setTimeout(()=>{if(document.visibilityState==='visible'&&modal.hidden)open()},1200)});closeButton.addEventListener('click',close);modal.addEventListener('click',event=>{if(event.target===modal)close()});document.addEventListener('keydown',event=>{if(modal.hidden)return;if(event.key==='Escape'){event.preventDefault();close();return}if(event.key==='Tab'){const items=[...dialog.querySelectorAll('button:not([disabled]),a[href],[tabindex]:not([tabindex="-1"])')].filter(item=>!item.hidden);if(!items.length){event.preventDefault();dialog.focus();return}const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});if(qr)qr.addEventListener('error',()=>{qr.hidden=true;if(fallback)fallback.hidden=false});if(copyButton)copyButton.addEventListener('click',async()=>{try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(CONTACT_CONFIG.wechatId);else{const input=document.createElement('textarea');input.value=CONTACT_CONFIG.wechatId;input.setAttribute('readonly','');input.style.position='fixed';input.style.opacity='0';document.body.appendChild(input);input.select();const copied=document.execCommand('copy');input.remove();if(!copied)throw new Error('Clipboard copy failed')}}catch(error){status.textContent=contactUi[locale].copy+' '+CONTACT_CONFIG.wechatId;return}status.textContent=(contactUi[locale]||contactUi.en).copied;clearTimeout(statusTimer);statusTimer=setTimeout(()=>{status.textContent=''},1800)})}
if(window.__BUILD_SEO__)render();else{const initialRoute=route();locale=initialRoute.lang;if(initialRoute.legacy)location.replace(pathFor(initialRoute.lang,initialRoute.page,initialRoute.sub));else wire();}

function articleOptimizationMarkup(slug,lang){
  if(slug!=='citizenship-by-investment-programs')return '';
  const d=window.seoComparison?.[lang];if(!d)return '';
  const urls=['https://www.invest.gov.tr/en/investmentguide/pages/acquiring-property-and-citizenship.aspx','https://www.cbiu.gov.dm/investment-options/economic-diversification-fund/','https://www.cbiu.gov.dm/investment-options/real-estate/','https://www.cbiu.gov.dm/faqs/','https://imagrenada.gd/wp-content/uploads/2024/07/Update-to-Circular-No.-2-Minimum-Investment-Threshold-July-3-2024.pdf'];
  return `<section class="seo-comparison" aria-labelledby="comparison-summary"><h2 id="comparison-summary">${esc(d.heading)}</h2><div class="seo-table-scroll" role="region" aria-label="${esc(d.heading)}" tabindex="0"><table><caption>${esc(d.caption)}</caption><thead><tr>${d.countries.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${d.rows.map(row=>`<tr><th scope="row">${esc(row[0])}</th>${row.slice(1).map((x,i)=>`<td data-country="${esc(d.countries[i+1])}">${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p>${esc(d.note)}</p><p>${esc(d.sources)}: ${urls.map((u,i)=>`<a href="${u}" target="_blank" rel="noopener noreferrer">${['Invest in Türkiye','Dominica EDF','Dominica real estate','Dominica CBIU FAQ','Grenada IMA'][i]}</a>`).join(' · ')}</p><p><a href="${pathFor(lang,'investment')}">${esc(d.guide)}</a> · <a href="${pathFor(lang,'igaturkishcitizenshipbyinvestment')}">${esc(d.lawyer)}</a></p><p class="source-note"><time datetime="2026-10-21">${esc(d.date)}</time></p></section>`;
}

function articleRevisionMarkup(slug,lang){
 if(slug==='citizenship-by-investment-programs'||!window.articleContentUpdates?.[slug])return '';
 const labels={en:'Content corrections updated: 21 October 2026',tr:'İçerik düzeltmeleri: 21 Ekim 2026',zh:'内容修订日期：2026年10月21日',ar:'تاريخ تصحيح المحتوى: 21 أكتوبر 2026'};
 return `<p class="source-note"><time datetime="${window.articleContentUpdates[slug]}">${esc(labels[lang])}</time></p>`;
}
